    if($('#prompt'))$('#prompt').oninput=e=>{state.draft.prompt=e.target.value;$('#prompt-count').textContent=e.target.value.length;persist();};
    for(const [selector,key] of [['#scenario','scenario'],['#slide-count','count'],['#theme','theme']])$(selector).onchange=e=>{state.draft[key]=key==='count'?Number(e.target.value):e.target.value;persist();};
    if($('#source-file'))$('#source-file').onchange=e=>parseFile(e.target.files[0]);
