  if($('#project-search'))$('#project-search').oninput=e=>{query=e.target.value;$('#project-results').innerHTML=projectResults();};
  $$('[data-outline]').forEach(el=>el.oninput=e=>{const p=current();if(p.status==='running')return;const s=p.outline.find(s=>s.id===el.dataset.outline);if(s){s[el.dataset.field]=e.target.value;p.updatedAt=Date.now();persist();}});
