async function parseFile(file){
  if(!file||uploading)return;const error=msg=>{if($('#upload-error'))$('#upload-error').textContent=msg;else toast(msg);};
  if(!/\.(pdf|docx)$/i.test(file.name))return error('仅支持 DOCX 和 PDF，请转换格式后再试。');if(file.size>10*1024*1024)return error('文件超过 10MB，请压缩或拆分后上传。');if(!file.size)return error('文件为空，请选择有内容的文档。');
  uploading=true;state.draft.source=null;render();let pdfDoc;
  try{const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);let text='',pages=null;if(/\.docx$/i.test(file.name)){if(bytes[0]!==0x50||bytes[1]!==0x4b)throw new Error('文件内容与 DOCX 格式不符，请重新导出后上传。');text=await extractDocx(buffer);}else{
    if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw new Error('文件内容与 PDF 格式不符。');const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;pdfDoc=await pdfjs.getDocument({data:bytes,isEvalSupported:false,useSystemFonts:true}).promise;pages=pdfDoc.numPages;if(pages>50)throw new Error('PDF 超过 50 页，请拆分后上传。');for(let i=1;i<=pages;i++){const page=await pdfDoc.getPage(i);const content=await page.getTextContent();text+=content.items.map(x=>x.str||'').join(' ')+'\n';if(text.length>100000)throw new Error('文本超过 10 万字，请精简后上传。');}
  }
  text=text.trim();if(text.length<10)throw new Error('未提取到可用文本。扫描 PDF 暂不支持 OCR，请转换为文本版。');if(text.length>100000)throw new Error('文本超过 10 万字，请精简后上传。');state.draft.source={name:file.name,text,chars:text.length,pages};persist();
  }catch(e){error(e.name==='PasswordException'?'PDF 已加密，请解密后重新上传。':e.message||'解析失败，请尝试重新保存文件。');state.draft.source=null;}
  finally{await pdfDoc?.destroy();uploading=false;const message=$('#upload-error')?.textContent;render();if(message&&$('#upload-error'))$('#upload-error').textContent=message;}
}
